/* tools.js: search and filter the static tool list on tools/. The list itself is plain HTML
 * (generated by scripts/build-tools-page.mjs), so everything here is an enhancement. */
(function () {
  'use strict';
  const { $, $$, reduce } = window.DGBP;
  const list = $('#tList'), input = $('#tq'), countEl = $('#tCount'), empty = $('#tEmpty'), emptyQ = $('#tEmptyQ');
  if (!list || !input) return;
  const still = reduce();
  const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const reEsc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  /* ---------------------------------------------------------------- read the static list */
  const sections = $$('.tl-cat', list).map((sec) => {
    const ul = $('.tl-list', sec);
    const items = $$('.tl-i', ul).map((li) => {
      const a = $('.tl-name a', li);
      return {
        li, a, i: Number(li.dataset.i), id: li.id,
        name: a.textContent, nameL: a.textContent.toLowerCase(),
        desc: $('.tl-desc', li).textContent.toLowerCase(),
        kw: (li.dataset.k || '').toLowerCase(),
        shown: true, marked: false,
      };
    });
    return { sec, ul, c: Number(sec.dataset.c), slug: sec.id.replace(/^cat-/, ''), items, order: items.slice(), shown: true };
  });
  const TOTAL = sections.reduce((n, s) => n + s.items.length, 0);

  /* ---------------------------------------------------------------- the rail becomes filter buttons */
  const railNav = $('#catRail');
  const railBtns = [];
  if (railNav) {
    const group = document.createElement('div');
    group.className = 'cat-rail';
    group.setAttribute('role', 'group');
    group.setAttribute('aria-label', 'Filter by category');
    const ul = document.createElement('ul');
    ul.className = 'cat-list';
    $$('.cat-btn', railNav).forEach((a) => {
      const li = document.createElement('li');
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'cat-btn';
      b.dataset.c = a.dataset.c;
      b.setAttribute('aria-pressed', String(a.dataset.c === '-1'));
      b.innerHTML = a.innerHTML;
      li.appendChild(b);
      ul.appendChild(li);
      railBtns.push(b);
    });
    group.appendChild(ul);
    railNav.replaceWith(group);
    ul.addEventListener('click', (e) => {
      const b = e.target.closest('.cat-btn');
      if (!b) return;
      const c = Number(b.dataset.c);
      setCat(c === cat && c !== -1 ? -1 : c, true);
    });
  }

  /* ---------------------------------------------------------------- scoring, like the app's finder */
  function score(it, words) {
    let s = 0;
    for (const w of words) {
      let best = 0;
      if (it.nameL.startsWith(w)) best = 6;
      else if (new RegExp('(^|[\\s(/&-])' + reEsc(w)).test(it.nameL)) best = 4;
      else if (it.nameL.includes(w)) best = 3;
      else if (it.kw.includes(w)) best = 2;
      else if (it.id.includes(w)) best = 1.5;
      else if (it.desc.includes(w)) best = 1;
      if (!best) return 0;
      s += best;
    }
    return s;
  }
  function mark(name, words) {
    let out = esc(name);
    for (const w of words) {
      const re = new RegExp('(' + reEsc(esc(w)) + ')', 'i');
      if (!/<mark>/.test(out) || !re.test(out.replace(/<mark>.*?<\/mark>/g, ''))) out = out.replace(re, '<mark>$1</mark>');
    }
    return out;
  }

  /* ---------------------------------------------------------------- run */
  let cat = -1;
  const live = document.createElement('p');
  live.className = 'sr-only';
  live.setAttribute('aria-live', 'polite');
  countEl.after(live);
  countEl.removeAttribute('aria-live');
  countEl.setAttribute('aria-hidden', 'true');
  let liveTimer = 0;

  function run(fromTyping) {
    const q = input.value.trim().toLowerCase();
    const words = q.split(/\s+/).filter(Boolean);
    const fresh = [];
    let total = 0;
    const perCat = new Map();
    const secOrder = [];
    for (const s of sections) {
      const scored = [];
      for (const it of s.items) {
        const sc = words.length ? score(it, words) : 1;
        if (sc > 0) scored.push({ it, sc });
      }
      perCat.set(s.c, scored.length);
      const inCat = cat === -1 || cat === s.c;
      const visible = inCat ? scored : [];
      const vis = new Set(visible.map((x) => x.it));
      // order inside the category: best match first, otherwise the catalog order
      const order = words.length ? visible.slice().sort((a, b) => b.sc - a.sc || a.it.i - b.it.i).map((x) => x.it) : s.items;
      if (order.some((it, k) => s.order[k] !== it) || order.length !== s.order.length) {
        for (const it of (words.length ? order.concat(s.items.filter((x) => !vis.has(x))) : s.items)) s.ul.appendChild(it.li);
        s.order = order.slice();
      }
      for (const it of s.items) {
        const show = vis.has(it);
        if (show && !it.shown) fresh.push(it.li);
        if (show !== it.shown) { it.li.hidden = !show; it.shown = show; }
        if (show && words.length) { it.a.innerHTML = mark(it.name, words); it.marked = true; }
        else if (it.marked) { it.a.textContent = it.name; it.marked = false; }
      }
      const secShown = visible.length > 0;
      if (secShown !== s.shown) { s.sec.hidden = !secShown; s.shown = secShown; }
      total += visible.length;
      secOrder.push({ s, best: visible.length ? Math.max(...visible.map((x) => x.sc)) : 0 });
    }
    // categories with the strongest match first while searching
    const wantOrder = words.length ? secOrder.slice().sort((a, b) => b.best - a.best || a.s.c - b.s.c).map((x) => x.s) : sections;
    const now = $$('.tl-cat', list);
    if (wantOrder.some((s, k) => now[k] !== s.sec)) wantOrder.forEach((s) => list.appendChild(s.sec));

    // rail counts follow the search
    for (const b of railBtns) {
      const c = Number(b.dataset.c);
      const n = c === -1 ? [...perCat.values()].reduce((a, v) => a + v, 0) : perCat.get(c) || 0;
      const nEl = $('.cat-btn-n', b);
      if (nEl.textContent !== String(n)) nEl.textContent = String(n);
      b.classList.toggle('is-empty', n === 0);
    }

    const catName = cat === -1 ? '' : $(`#h-${sections.find((s) => s.c === cat).slug}`).childNodes[1].textContent.trim();
    const label = total === 0 ? 'No tools' : total === 1 ? '1 tool' : `${total} tools`;
    countEl.textContent = label + (catName ? ` in ${catName}` : '');
    empty.hidden = total !== 0;
    if (total === 0) emptyQ.textContent = input.value.trim();
    clearTimeout(liveTimer);
    liveTimer = setTimeout(() => { live.textContent = total === 0 ? `No tools match ${input.value.trim()}.` : `${label}${catName ? ' in ' + catName : ''}${words.length ? ' match' + (total === 1 ? 'es' : '') : ''}.`; }, 450);

    if (fresh.length && !still && fresh.length < 120) {
      fresh.forEach((li) => li.classList.remove('is-new'));
      void list.offsetWidth;
      fresh.forEach((li) => li.classList.add('is-new'));
    }

    // keep the URL shareable
    try {
      const u = new URL(location.href);
      if (q) u.searchParams.set('q', input.value.trim()); else u.searchParams.delete('q');
      if (cat !== -1) u.searchParams.set('c', sections.find((s) => s.c === cat).slug); else u.searchParams.delete('c');
      history.replaceState(null, '', u.pathname + u.search + u.hash);
    } catch (e) { /* file:// or sandboxed */ }

    if (fromTyping) toCatalogTop();
  }

  function toCatalogTop() {
    const top = $('#catalog').getBoundingClientRect().top;
    if (top < 0) window.scrollTo({ top: window.scrollY + top, behavior: 'auto' });
  }
  function setCat(c, fromClick) {
    cat = c;
    railBtns.forEach((b) => b.setAttribute('aria-pressed', String(Number(b.dataset.c) === c)));
    run(false);
    if (fromClick) {
      toCatalogTop();
      const b = railBtns.find((x) => Number(x.dataset.c) === c);
      if (b && b.parentElement.parentElement.scrollWidth > b.parentElement.parentElement.clientWidth) b.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    }
  }

  input.addEventListener('input', () => run(true));

  /* ---------------------------------------------------------------- keyboard */
  const visibleLinks = () => $$('.tl-i:not([hidden]) .tl-name a', list).filter((a) => !a.closest('.tl-cat').hidden);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowDown') { const l = visibleLinks(); if (l.length) { e.preventDefault(); l[0].focus(); } }
    else if (e.key === 'Escape' && input.value) { e.preventDefault(); input.value = ''; run(false); }
  });
  list.addEventListener('keydown', (e) => {
    const a = e.target.closest('.tl-name a');
    if (!a) return;
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      const l = visibleLinks();
      const k = l.indexOf(a);
      e.preventDefault();
      if (e.key === 'ArrowDown' && k < l.length - 1) l[k + 1].focus();
      else if (e.key === 'ArrowUp') { if (k > 0) l[k - 1].focus(); else input.focus(); }
    } else if (e.key === 'Escape') { e.preventDefault(); input.focus(); }
  });
  document.addEventListener('keydown', (e) => {
    if (e.key !== '/' || e.metaKey || e.ctrlKey || e.altKey) return;
    const t = e.target;
    if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
    e.preventDefault();
    input.focus();
    input.select();
  });

  /* ---------------------------------------------------------------- start from the URL */
  try {
    const p = new URLSearchParams(location.search);
    const q = p.get('q');
    const c = p.get('c');
    if (q) input.value = q;
    const s = c && sections.find((x) => x.slug === c);
    if (s) { cat = s.c; railBtns.forEach((b) => b.setAttribute('aria-pressed', String(Number(b.dataset.c) === cat))); }
  } catch (e) { /* ignore */ }
  if (input.value || cat !== -1) run(false);
  else countEl.textContent = `${TOTAL} tools`;
})();
